typedef double ld;
typedef pair<ld,ld> P;

ld cross(P O, P A, P B) {
    return (A.first-O.first)*(B.second-O.second) - (A.second-O.second)*(B.first-O.first);
}

P intersect(P a, P b, P c, P d) {
    ld A1 = b.second-a.second, B1 = a.first-b.first, C1 = A1*a.first+B1*a.second;
    ld A2 = d.second-c.second, B2 = c.first-d.first, C2 = A2*c.first+B2*c.second;
    ld det = A1*B2 - A2*B1;
    return {(C1*B2-C2*B1)/det, (A1*C2-A2*C1)/det};
}

vector<P> clip(vector<P> poly, P a, P b) {
    vector<P> res;
    int n = poly.size();
    for(int i = 0; i < n; i++) {
        P c = poly[i], d = poly[(i+1)%n];
        ld cc = cross(a,b,c), dc = cross(a,b,d);
        if(cc >= 0) res.push_back(c);
        if((cc > 0 && dc < 0) || (cc < 0 && dc > 0))
            res.push_back(intersect(a,b,c,d));
    }
    return res;
}

ld area(vector<P>& poly) {
    ld s = 0;
    int n = poly.size();
    for(int i = 0; i < n; i++) {
        s += poly[i].first*poly[(i+1)%n].second - poly[(i+1)%n].first*poly[i].second;
    }
    return abs(s)/2;
}

