#include <bits/stdc++.h>
using namespace std;

struct Point {
    double x, y;
};

static const double EPS = 1e-9;

double cross(const Point& a, const Point& b, const Point& c) {
    // (b-a) x (c-a)
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

double polygonArea(const vector<Point>& p) {
    int n = (int)p.size();
    if (n < 3) return 0.0;
    double s = 0;
    for (int i = 0; i < n; ++i) {
        int j = (i + 1) % n;
        s += p[i].x * p[j].y - p[i].y * p[j].x;
    }
    return fabs(s) * 0.5;
}

Point lineIntersection(const Point& a, const Point& b, const Point& p, const Point& q) {
    // intersection of lines ab and pq
    double A1 = b.y - a.y;
    double B1 = a.x - b.x;
    double C1 = A1 * a.x + B1 * a.y;

    double A2 = q.y - p.y;
    double B2 = p.x - q.x;
    double C2 = A2 * p.x + B2 * p.y;

    double det = A1 * B2 - A2 * B1;
    if (fabs(det) < EPS) return {0, 0}; // parallel; should not happen in valid clipping cases
    return {
        (B2 * C1 - B1 * C2) / det,
        (A1 * C2 - A2 * C1) / det
    };
}

bool insideLeft(const Point& p, double xmin)   { return p.x >= xmin - EPS; }
bool insideRight(const Point& p, double xmax)  { return p.x <= xmax + EPS; }
bool insideBottom(const Point& p, double ymin) { return p.y >= ymin - EPS; }
bool insideTop(const Point& p, double ymax)    { return p.y <= ymax + EPS; }

vector<Point> clipLeft(const vector<Point>& poly, double xmin) {
    vector<Point> out;
    int n = (int)poly.size();
    for (int i = 0; i < n; ++i) {
        Point cur = poly[i], prev = poly[(i + n - 1) % n];
        bool ic = insideLeft(cur, xmin);
        bool ip = insideLeft(prev, xmin);

        if (ip && ic) {
            out.push_back(cur);
        } else if (ip && !ic) {
            Point inter = lineIntersection(prev, cur, {xmin, -1e18}, {xmin, 1e18});
            out.push_back(inter);
        } else if (!ip && ic) {
            Point inter = lineIntersection(prev, cur, {xmin, -1e18}, {xmin, 1e18});
            out.push_back(inter);
            out.push_back(cur);
        }
    }
    return out;
}

