// Cross product of vectors (p1-p0) and (p2-p0)
double cross(Point p0, Point p1, Point p2) {
    return (p1.x - p0.x) * (p2.y - p0.y) - (p1.y - p0.y) * (p2.x - p0.x);
}

// Check if point p is inside rectangle defined by bottom-left and top-right
int pointInRect(Point p, Point bl, Point tr) {
    return p.x >= bl.x && p.x <= tr.x && p.y >= bl.y && p.y <= tr.y;
}

// Check if two line segments (a1-a2) and (b1-b2) intersect, return intersection point
int segmentIntersect(Point a1, Point a2, Point b1, Point b2, Point *inter) {
    double d1 = cross(a1, a2, b1);
    double d2 = cross(a1, a2, b2);
    double d3 = cross(b1, b2, a1);
    double d4 = cross(b1, b2, a2);

    if (((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0)) &&
        ((d3 > 0 && d4 < 0) || (d3 < 0 && d4 > 0))) {
        // Compute intersection
        double t = d1 / (d1 - d2);
        inter->x = a1.x + t * (a2.x - a1.x);
        inter->y = a1.y + t * (a2.y - a1.y);
        return 1;
    }

    // Check collinear cases (if needed for edge cases)
    if (d1 == 0 && d2 == 0 && d3 == 0 && d4 == 0) {
        // Collinear overlapping - not handled in this simple version
        return 0;
    }
    return 0;
}

// Compute polygon area using shoelace formula
double polygonArea(Point *poly, int n) {
    double area = 0.0;
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        area += poly[i].x * poly[j].y;
        area -= poly[j].x * poly[i].y;
    }
    return fabs(area) / 2.0;
}

// Sutherland-Hodgman polygon clipping against a half-plane (line from p1 to p2)
int clipByEdge(Point *input, int n, Point p1, Point p2, Point *output) {
    int outCount = 0;
    for (int i = 0; i < n; i++) {
        Point current = input[i];
        Point next = input[(i + 1) % n];

        double d1 = cross(p1, p2, current);
        double d2 = cross(p1, p2, next);

        // Inside if cross >= 0 (considering clockwise/counterclockwise)
        // We'll use >= 0 for inside
        if (d1 >= 0) {
            output[outCount++] = current;
        }

        if ((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0)) {
            Point inter;
            segmentIntersect(current, next, p1, p2, &inter);
            output[outCount++] = inter;
        }
    }
    return outCount;
}

int comparePoints(const void *a, const void *b) {
    Point *p1 = (Point *)a;
    Point *p2 = (Point *)b;
    if (p1->x < p2->x) return -1;
    if (p1->x > p2->x) return 1;
    if (p1->y < p2->y) return -1;
    if (p1->y > p2->y) return 1;
    return 0;
}

// Clip polygon against rectangle (defined by two corners)
int clipPolygonByRect(Point *poly, int n, Point bl, Point tr, Point *result) {
    Point temp[MAX_POINTS * 4];
    int count = n;

    // Copy polygon
    for (int i = 0; i < n; i++) {
        temp[i] = poly[i];
    }

    // Clip against each of the 4 edges of rectangle
    // Rectangle edges: left, right, bottom, top (in counterclockwise order)

    // Left edge (bottom to top)
    Point p1 = {bl.x, bl.y};
    Point p2 = {bl.x, tr.y};
    count = clipByEdge(temp, count, p1, p2, result);
    for (int i = 0; i < count; i++) temp[i] = result[i];

    // Top edge (left to right)
    p1 = (Point){bl.x, tr.y};
    p2 = (Point){tr.x, tr.y};
    count = clipByEdge(temp, count, p1, p2, result);
    for (int i = 0; i < count; i++) temp[i] = result[i];

    // Right edge (top to bottom)
    p1 = (Point){tr.x, tr.y};
    p2 = (Point){tr.x, bl.y};
    count = clipByEdge(temp, count, p1, p2, result);
    for (int i = 0; i < count; i++) temp[i] = result[i];

    // Bottom edge (right to left)
    p1 = (Point){tr.x, bl.y};
    p2 = (Point){bl.x, bl.y};
    count = clipByEdge(temp, count, p1, p2, result);

    return count;
}

