#include <math.h>

#define MAXP 10000
#define EPS 1e-9

typedef struct {
    double x, y;
} Point;

static double cross(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

static double polygon_area(Point *p, int n) {
    double s = 0.0;
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        s += p[i].x * p[j].y - p[j].x * p[i].y;
    }
    return fabs(s) * 0.5;
}

static Point line_intersection(Point a, Point b, Point p, Point q) {
    // intersection of lines ab and pq
    Point r;
    double A1 = b.y - a.y;
    double B1 = a.x - b.x;
    double C1 = A1 * a.x + B1 * a.y;

    double A2 = q.y - p.y;
    double B2 = p.x - q.x;
    double C2 = A2 * p.x + B2 * p.y;

    double det = A1 * B2 - A2 * B1;
    if (fabs(det) < EPS) {
        r.x = a.x;
        r.y = a.y;
        return r;
    }
    r.x = (B2 * C1 - B1 * C2) / det;
    r.y = (A1 * C2 - A2 * C1) / det;
    return r;
}

static int inside_left(Point a, Point b, Point p) {
    return cross(a, b, p) >= -EPS;
}

static int clip_polygon(Point *subject, int n, Point a, Point b, Point *out) {
    int m = 0;
    for (int i = 0; i < n; i++) {
        Point cur = subject[i];
        Point prev = subject[(i + n - 1) % n];
        int icur = inside_left(a, b, cur);
        int iprev = inside_left(a, b, prev);

        if (icur) {
            if (!iprev) out[m++] = line_intersection(prev, cur, a, b);
            out[m++] = cur;
        } else if (iprev) {
            out[m++] = line_intersection(prev, cur, a, b);
        }
    }
    return m;
}

int main(void) {
    int n;
    while (scanf("%d", &n) == 1 && n) {
        Point poly[MAXP], tmp1[MAXP], tmp2[MAXP];
        for (int i = 0; i < n; i++) {
