            }
        }

        int m = n;
        for (int i = 0; i < n; i++) tmp1[i] = poly[i];

        for (int i = 0; i < 4; i++) {
            Point a = rect[i];
            Point b = rect[(i + 1) % 4];
            m = clip_polygon(tmp1, m, a, b, tmp2);
            for (int j = 0; j < m; j++) tmp1[j] = tmp2[j];
            if (m == 0) break;
        }

        double covered = (m > 0) ? polygon_area(tmp1, m) : 0.0;
        double uncovered = area_window - covered;

        long long ans = (long long)floor(uncovered + 0.5);
        printf("%lld\n", ans);
    }
    return 0;
}

