    }

    // Intersection of a line segment (p1->p2) with a clipping edge (given by two points on the edge)
    static Point intersect(Point p1, Point p2, Point a, Point b) {
        double dx = b.x - a.x;
        double dy = b.y - a.y;
        double t = ((p1.x - a.x) * dy - (p1.y - a.y) * dx) /
                   ((p2.x - p1.x) * dy - (p2.y - p1.y) * dx);
        return new Point(p1.x + t * (p2.x - p1.x), p1.y + t * (p2.y - p1.y));
    }

    // Inside test for a point relative to a clipping edge (a->b)
    static boolean inside(Point p, Point a, Point b) {
        return (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x) >= 0;
    }

    // Clip polygon against one edge (a->b)
    static List<Point> clipEdge(List<Point> poly, Point a, Point b) {
        List<Point> out = new ArrayList<>();
        int n = poly.size();
        if (n == 0) return out;
        Point prev = poly.get(n - 1);
        boolean prevInside = inside(prev, a, b);
        for (Point cur : poly) {
            boolean curInside = inside(cur, a, b);
            if (curInside) {
                if (!prevInside) {
                    out.add(intersect(prev, cur, a, b));
                }
                out.add(cur);
            } else if (prevInside) {
                out.add(intersect(prev, cur, a, b));
            }
            prev = cur;
            prevInside = curInside;
        }
        return out;
    }

    // Clip polygon against a rectangle (given by two opposite corners)
    static List<Point> clipRectangle(List<Point> poly, double x1, double y1, double x2, double y2) {
        double minX = Math.min(x1, x2);
        double maxX = Math.max(x1, x2);
        double minY = Math.min(y1, y2);
        double maxY = Math.max(y1, y2);

        // Four edges: left, top, right, bottom (counterclockwise)
        Point a = new Point(minX, minY);
        Point b = new Point(maxX, minY);
        Point c = new Point(maxX, maxY);
        Point d = new Point(minX, maxY);

        List<Point> result = poly;
        result = clipEdge(result, a, b);
        result = clipEdge(result, b, c);
        result = clipEdge(result, c, d);
        result = clipEdge(result, d, a);
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == 0) break;
            List<Point> window = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                double x = sc.nextDouble();
                double y = sc.nextDouble();
                window.add(new Point(x, y));
            }
            double rx1 = sc.nextDouble();
            double ry1 = sc.nextDouble();
            double rx2 = sc.nextDouble();
            double ry2 = sc.nextDouble();

            double windowArea = polygonArea(window);
            List<Point> clipped = clipRectangle(window, rx1, ry1, rx2, ry2);
            double overlapArea = polygonArea(clipped);
            double uncovered = windowArea - overlapArea;
            System.out.println((int) Math.round(uncovered));
        }
        sc.close();
    }
}

import java.util.*;

public class Main {
    static double[] intersectPoint(double x1, double y1, double x2, double y2,
                                    double x3, double y3, double x4, double y4) {
        double denom = (x1-x2)*(y3-y4) - (y1-y2)*(x3-x4);
        if (Math.abs(denom) < 1e-10) return null;
        double t = ((x1-x3)*(y3-y4) - (y1-y3)*(x3-x4)) / denom;
        return new double[]{x1 + t*(x2-x1), y1 + t*(y2-y1)};
    }

    static List<double[]> clip(List<double[]> poly, double[] edge1, double[] edge2) {
        List<double[]> result = new ArrayList<>();
        int n = poly.size();
        for (int i = 0; i < n; i++) {
            double[] cur = poly.get(i);
            double[] prev = poly.get((i-1+n)%n);
            double d1 = (edge2[0]-edge1[0])*(prev[1]-edge1[1]) - (edge2[1]-edge1[1])*(prev[0]-edge1[0]);
            double d2 = (edge2[0]-edge1[0])*(cur[1]-edge1[1]) - (edge2[1]-edge1[1])*(cur[0]-edge1[0]);
            if (d2 >= 0) { // cur is inside
                if (d1 < 0) { // prev was outside
                    double[] pt = intersectPoint(prev[0],prev[1],cur[0],cur[1],edge1[0],edge1[1],edge2[0],edge2[1]);
                    if (pt != null) result.add(pt);
                }
                result.add(cur);
            } else if (d1 >= 0) { // prev inside, cur outside
                double[] pt = intersectPoint(prev[0],prev[1],cur[0],cur[1],edge1[0],edge1[1],edge2[0],edge2[1]);
                if (pt != null) result.add(pt);
            }
        }
        return result;
    }

    static double area(List<double[]> poly) {
        double a = 0;
        int n = poly.size();
        for (int i = 0; i < n; i++) {
            double[] p1 = poly.get(i), p2 = poly.get((i+1)%n);
            a += p1[0]*p2[1] - p2[0]*p1[1];
        }
        return Math.abs(a)/2.0;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == 0) break;
            List<double[]> window = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                double x = sc.nextDouble(), y = sc.nextDouble();
                window.add(new double[]{x, y});
            }
            // Read rectangle (4 vertices)
            List<double[]> rect = new ArrayList<>();
            for (int i = 0; i < 4; i++) {
                double x = sc.nextDouble(), y = sc.nextDouble();
                rect.add(new double[]{x, y});
            }

            // Clip window by rectangle using Sutherland-Hodgman
            List<double[]> clipped = new ArrayList<>(window);
            int m = rect.size();
            for (int i = 0; i < m; i++) {
                if (clipped.isEmpty()) break;
                double[] e1 = rect.get(i), e2 = rect.get((i+1)%m);
                clipped = clip(clipped, e1, e2);
            }

            double windowArea = area(window);
            double intersectionArea = clipped.isEmpty() ? 0 : area(clipped);
            double uncovered = windowArea - intersectionArea;
            System.out.println(Math.round(uncovered));
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    static final double EPS = 1e-9;

    static List<Point> clipLeft(List<Point> poly, double xmin) {
        List<Point> res = new ArrayList<>();
        int n = poly.size();
        for (int i = 0; i < n; i++) {
            Point a = poly.get(i);
            Point b = poly.get((i + 1) % n);
            boolean ina = a.x >= xmin - EPS;
            boolean inb = b.x >= xmin - EPS;

            if (ina && inb) {
                res.add(new Point(b.x, b.y));
            } else if (ina && !inb) {
                double t = (xmin - a.x) / (b.x - a.x);
                double y = a.y + t * (b.y - a.y);
                res.add(new Point(xmin, y));
            } else if (!ina && inb) {
                double t = (xmin - a.x) / (b.x - a.x);
                double y = a.y + t * (b.y - a.y);
                res.add(new Point(xmin, y));
                res.add(new Point(b.x, b.y));
            }
        }
        return res;
    }

    static List<Point> clipRight(List<Point> poly, double xmax) {
        List<Point> res = new ArrayList<>();
        int n = poly.size();
        for (int i = 0; i < n; i++) {
            Point a = poly.get(i);
            Point b = poly.get((i + 1) % n);
            boolean ina = a.x <= xmax + EPS;
            boolean inb = b.x <= xmax + EPS;

            if (ina && inb) {
                res.add(new Point(b.x, b.y));
            } else if (ina && !inb) {
                double t = (xmax - a.x) / (b.x - a.x);
                double y = a.y + t * (b.y - a.y);
                res.add(new Point(xmax, y));
            } else if (!ina && inb) {
                double t = (xmax - a.x) / (b.x - a.x);
                double y = a.y + t * (b.y - a.y);
                res.add(new Point(xmax, y));
                res.add(new Point(b.x, b.y));
            }
        }
        return res;
    }

    static List<Point> clipBottom(List<Point> poly, double ymin) {
        List<Point> res = new ArrayList<>();
        int n = poly.size();
        for (int i = 0; i < n; i++) {
            Point a = poly.get(i);
            Point b = poly.get((i + 1) % n);
            boolean ina = a.y >= ymin - EPS;
            boolean inb = b.y >= ymin - EPS;

            if (ina && inb) {
                res.add(new Point(b.x, b.y));
            } else if (ina && !inb) {
                double t = (ymin - a.y) / (b.y - a.y);
                double x = a.x + t * (b.x - a.x);
                res.add(new Point(x, ymin));
            } else if (!ina && inb) {
                double t = (ymin - a.y) / (b.y - a.y);
                double x = a.x + t * (b.x - a.x);
                res.add(new Point(x, ymin));
                res.add(new Point(b.x, b.y));
            }
        }
        return res;
    }

    static List<Point> clipTop(List<Point> poly, double ymax) {
        List<Point> res = new ArrayList<>();
        int n = poly.size();
        for (int i = 0; i < n; i++) {
            Point a = poly.get(i);
            Point b = poly.get((i + 1) % n);
            boolean ina = a.y <= ymax + EPS;
            boolean inb = b.y <= ymax + EPS;

            if (ina && inb) {
                res.add(new Point(b.x, b.y));
            } else if (ina && !inb) {
                double t = (ymax - a.y) / (b.y - a.y);
                double x = a.x + t * (b.x - a.x);
                res.add(new Point(x, ymax));
            } else if (!ina && inb) {
                double t = (ymax - a.y) / (b.y - a.y);
                double x = a.x + t * (b.x - a.x);
                res.add(new Point(x, ymax));
                res.add(new Point(b.x, b.y));
            }
        }
        return res;
    }

    static double polygonArea(List<Point> poly) {
        int n = poly.size();
        if (n < 3) return 0.0;
        double s = 0;
        for (int i = 0; i < n; i++) {
            Point a = poly.get(i);
            Point b = poly.get((i + 1) % n);
            s += a.x * b.y - a.y * b.x;
        }
        return Math.abs(s) * 0.5;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            int n;
            try {
                n = fs.nextInt();
            } catch (Exception e) {
                break;
            }
            if (n == 0) break;

            List<Point> window = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                int x = fs.nextInt();
                int y = fs.nextInt();
                window.add(new Point(x, y));
            }

            int x1 = fs.nextInt();
            int y1 = fs.nextInt();
            int x2 = fs.nextInt();
            int y2 = fs.nextInt();

            double xmin = Math.min(x1, x2);
            double xmax = Math.max(x1, x2);
            double ymin = Math.min(y1, y2);
            double ymax = Math.max(y1, y2);

            double totalArea = polygonArea(window);

            List<Point> inter = window;
            inter = clipLeft(inter, xmin);
            inter = clipRight(inter, xmax);
            inter = clipBottom(inter, ymin);
            inter = clipTop(inter, ymax);

            double coveredArea = polygonArea(inter);
            long answer = Math.round(totalArea - coveredArea);

            out.append(answer).append('\n');
        }

        System.out.print(out.toString());
    }
}
